1	//! The validated authorization capability and the staleness rules behind it.
2	
3	use std::collections::BTreeMap;
4	use std::path::Path;
5	
6	use callisto_model::{
7	    AbsentProof, ApplyPermit, CommandRunner, ExactEvidence, ExecutionTrustProfileV1, ProviderObservationV1,
8	    ReleaseDecisionV1, ReleaseIntentError, ReleaseIntentV1, ReleaseOperationId, SourceIdentity,
9	};
10	use callisto_vcs::access::{GitCommitTrustEvidence, GitHeadDisposition};
11	
12	use crate::error::ReleasePreconditionRequirement;
13	use crate::{DependencyResolver, GraphError, ProjectLocator, Workspace};
14	
15	use super::binding::{recheck_git_remote, PreparedGitRemote};
16	use super::derive::{
17	    artifact_policy_from_intent, derive_release_intent, derive_release_intent_with_prepared, ArtifactBuildPolicy,
18	    GitRemoteRequirement,
19	};
20	use super::provider::{
21	    checked_provider_for, EffectAuthorization, PreparedOperation, ProviderContext, ProviderRequest, ReleasePreflight,
22	    ReleaseProviderSet,
23	};
24	use super::release_artifacts::VerifiedArtifactManifest;
25	use super::StaleReason;
26	
27	/// Graph-private inputs prepared from the same fresh observation as an intent.
28	/// Retaining them in the capability prevents a validated public intent being
29	/// paired with new inputs.
30	#[derive(Debug)]
31	pub(crate) struct PreparedReleaseInputs {
32	    pub(crate) root: std::path::PathBuf,
33	    pub(crate) source: SourceIdentity,
34	    trust: GitCommitTrustEvidence,
35	    git_remote: Option<PreparedGitRemote>,
36	    pub(crate) operations: BTreeMap<ReleaseOperationId, PreparedOperation>,
37	}
38	
39	/// In-memory, non-transferable proof that an intent was rebuilt from a fresh
40	/// workspace observation. It is intentionally neither cloneable nor serializable.
41	pub struct ValidatedReleaseIntent<'a> {
42	    intent: ReleaseIntentV1,
43	    prepared: PreparedReleaseInputs,
44	    runner: &'a dyn CommandRunner,
45	}
46	
47	impl std::fmt::Debug for ValidatedReleaseIntent<'_> {
48	    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
49	        formatter
50	            .debug_struct("ValidatedReleaseIntent")
51	            .field("intent", &self.intent)
52	            .finish_non_exhaustive()
53	    }
54	}
55	
56	impl ValidatedReleaseIntent<'_> {
57	    pub fn intent(&self) -> &ReleaseIntentV1 {
58	        &self.intent
59	    }
60	
61	    #[cfg(test)]
62	    pub(crate) fn prepared(&self) -> &PreparedReleaseInputs {
63	        &self.prepared
64	    }
65	
66	    fn context(&self) -> ProviderContext<'_> {
67	        ProviderContext::new(&self.prepared.root, self.runner, self.prepared.git_remote.as_ref())
68	    }
69	
70	    fn prepared_operation(&self, id: &ReleaseOperationId) -> Result<&PreparedOperation, GraphError> {
71	        self.prepared
72	            .operations
73	            .get(id)
74	            .ok_or_else(|| GraphError::ReleaseInvariant {
75	                detail: format!("no prepared operation for `{id:?}`"),
76	            })
77	    }
78	}
79	
80	/// The production provider set: every operation is routed to the adapter
81	/// prepared for it during fresh validation, so no caller-supplied path,
82	/// endpoint, tag, package name, or version can reach a provider.
83	impl ReleaseProviderSet for ValidatedReleaseIntent<'_> {
84	    fn intent(&self) -> &ReleaseIntentV1 {
85	        &self.intent
86	    }
87	
88	    fn recheck_trust(&self) -> Result<(), GraphError> {
89	        let evidence = callisto_vcs::GitAccess::new(&self.prepared.root, self.runner).observe_git_commit_trust()?;
90	        if evidence.identity() != self.prepared.trust.identity() || source_from_trust(&evidence) != self.prepared.source
91	        {
92	            return Err(GraphError::ReleaseIntentStale {
93	                reason: StaleReason::trust_evidence_changed(),
94	            });
95	        }
96	        // An unreadable remote propagates as itself; only a readable, different remote is "stale".
97	        if let Some(expected) = self.prepared.git_remote.as_ref() {
98	            recheck_git_remote(&self.prepared.root, self.runner, expected)?;
99	        }
100	        Ok(())
101	    }
102	
103	    fn preflight(
104	        &self,
105	        id: &ReleaseOperationId,
106	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
107	    ) -> Result<ReleasePreflight, GraphError> {
108	        let operation = self.prepared_operation(id)?;
109	        checked_provider_for(operation)?.preflight(
110	            &self.context(),
111	            &ProviderRequest {
112	                id,
113	                operation,
114	                artifacts,
115	            },
116	        )
117	    }
118	
119	    fn observe(
120	        &self,
121	        id: &ReleaseOperationId,
122	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
123	    ) -> Result<ProviderObservationV1, GraphError> {
124	        let operation = self.prepared_operation(id)?;
125	        checked_provider_for(operation)?.observe(
126	            &self.context(),
127	            &ProviderRequest {
128	                id,
129	                operation,
130	                artifacts,
131	            },
132	        )
133	    }
134	
135	    fn publish(
136	        &self,
137	        permit: &ApplyPermit,
138	        proof: &AbsentProof,
139	        id: &ReleaseOperationId,
140	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
141	    ) -> Result<ExactEvidence, GraphError> {
142	        let operation = self.prepared_operation(id)?;
143	        checked_provider_for(operation)?.publish(
144	            &self.context(),
145	            &ProviderRequest {
146	                id,
147	                operation,
148	                artifacts,
149	            },
150	            &EffectAuthorization { permit, proof },
151	        )
152	    }
153	}
154	
155	/// Builds a release intent from a fresh root-bound observation.
156	pub fn build_release_intent<L: ProjectLocator, R: CommandRunner>(
157	    root: &Path,
158	    locator: &L,
159	    runner: &R,
160	    decision: &ReleaseDecisionV1,
161	    trust_profile: ExecutionTrustProfileV1,
162	) -> Result<ReleaseIntentV1, GraphError> {
163	    let root = canonical_root(root)?;
164	    let workspace = Workspace::load(root.clone(), locator, runner)?;
165	    let source = observe_source(&workspace, trust_profile, ReleaseCheckout::Detached)?;
166	    let intent = derive_release_intent(
167	        &workspace,
168	        decision,
169	        source.clone(),
170	        trust_profile,
171	        None,
172	        GitRemoteRequirement::Required,
173	    )?;
174	
175	    // Recheck after all input reads. A concurrent edit or checkout cannot be
176	    // authorized merely because it happened after the first check.
177	    if observe_source(&workspace, trust_profile, ReleaseCheckout::Detached)? != source {
178	        return Err(GraphError::ReleaseIntentStale {
179	            reason: StaleReason::source_identity_changed(),
180	        });
181	    }
182	    Ok(intent)
183	}
184	
185	/// Builds an intent whose declared binary slots are bound to the current
186	/// coordinator workflow. Callers recovering an old release source must pass
187	/// the current coordinator revision here, never substitute the source SHA.
188	pub fn build_release_intent_with_artifacts<L: ProjectLocator, R: CommandRunner>(
189	    root: &Path,
190	    locator: &L,
191	    runner: &R,
192	    decision: &ReleaseDecisionV1,
193	    trust_profile: ExecutionTrustProfileV1,
194	    artifact_policy: ArtifactBuildPolicy,
195	) -> Result<ReleaseIntentV1, GraphError> {
196	    let root = canonical_root(root)?;
197	    let workspace = Workspace::load(root.clone(), locator, runner)?;
198	    let source = observe_source(&workspace, trust_profile, ReleaseCheckout::Detached)?;
199	    let intent = derive_release_intent(
200	        &workspace,
201	        decision,
202	        source.clone(),
203	        trust_profile,
204	        Some(&artifact_policy),
205	        GitRemoteRequirement::Required,
206	    )?;
207	    if observe_source(&workspace, trust_profile, ReleaseCheckout::Detached)? != source {
208	        return Err(GraphError::ReleaseIntentStale {
209	            reason: StaleReason::source_identity_changed(),
210	        });
211	    }
212	    Ok(intent)
213	}
214	
215	/// Re-observes root, config, package discovery, manifests, Git evidence, and
216	/// the exact operation DAG before creating an opaque authorization capability.
217	pub fn validate_release_intent<'a, L: ProjectLocator, R: CommandRunner>(
218	    root: &Path,
219	    locator: &L,
220	    runner: &'a R,
221	    received: ReleaseIntentV1,
222	) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
223	    validate_intent(root, locator, runner, received, ReleaseCheckout::Detached)
224	}
225	
226	/// [`validate_release_intent`] for a local `callisto release`, which may run on any branch.
227	pub fn validate_local_release_intent<'a, L: ProjectLocator, R: CommandRunner>(
228	    root: &Path,
229	    locator: &L,
230	    runner: &'a R,
231	    received: ReleaseIntentV1,
232	) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
233	    validate_intent(root, locator, runner, received, ReleaseCheckout::AnyHead)
234	}
235	
236	fn validate_intent<'a, L: ProjectLocator, R: CommandRunner>(
237	    root: &Path,
238	    locator: &L,
239	    runner: &'a R,
240	    received: ReleaseIntentV1,
241	    checkout: ReleaseCheckout,
242	) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
243	    let root = canonical_root(root)?;
244	    let workspace = Workspace::load(root.clone(), locator, runner)?;
245	    let trust = observe_git_trust(&workspace, received.trust_profile, checkout)?;
246	    let source = source_from_trust(&trust);
247	    let artifact_policy = artifact_policy_from_intent(&received)?;
248	    let (expected, prepared) = derive_release_intent_with_prepared(
249	        &workspace,
250	        &received.decision,
251	        source.clone(),
252	        received.trust_profile,
253	        artifact_policy.as_ref(),
254	    )?;
255	    let final_trust = observe_git_trust(&workspace, received.trust_profile, checkout)?;
256	    if expected != received || final_trust.identity() != trust.identity() {
257	        return Err(GraphError::ReleaseIntentStale {
258	            reason: StaleReason::intent_differs_from_fresh_derivation(),
259	        });
260	    }
261	
262	    // Plan time is the last point before any effect at which an unusable
263	    // provider is still cheap to reject.
264	    for operation in prepared.operations.values() {
265	        checked_provider_for(operation)?;
266	    }
267	
268	    Ok(ValidatedReleaseIntent {
269	        prepared: PreparedReleaseInputs {
270	            root,
271	            source,
272	            trust: final_trust,
273	            git_remote: prepared.git_remote,
274	            operations: prepared.operations,
275	        },
276	        intent: received,
277	        runner,
278	    })
279	}
280	
281	pub(crate) fn canonical_root(root: &Path) -> Result<std::path::PathBuf, GraphError> {
282	    dunce::canonicalize(root).map_err(|error| GraphError::ReleaseInputRead {
283	        path: root.to_path_buf(),
284	        message: error.to_string(),
285	    })
286	}
287	
288	/// Which checkout a release may run from.
289	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
290	pub(crate) enum ReleaseCheckout {
291	    /// The exact detached commit a CI intent is planned and executed from.
292	    Detached,
293	    /// A local checkout on any branch; the source is HEAD's commit.
294	    AnyHead,
295	}
296	
297	pub(crate) fn observe_source<R: CommandRunner, D: DependencyResolver>(
298	    workspace: &Workspace<'_, R, D>,
299	    trust_profile: ExecutionTrustProfileV1,
300	    checkout: ReleaseCheckout,
301	) -> Result<SourceIdentity, GraphError> {
302	    Ok(source_from_trust(&observe_git_trust(
303	        workspace,
304	        trust_profile,
305	        checkout,
306	    )?))
307	}
308	
309	fn observe_git_trust<R: CommandRunner, D: DependencyResolver>(
310	    workspace: &Workspace<'_, R, D>,
311	    trust_profile: ExecutionTrustProfileV1,
312	    checkout: ReleaseCheckout,
313	) -> Result<GitCommitTrustEvidence, GraphError> {
314	    if !matches!(trust_profile, ExecutionTrustProfileV1::GitCommit) {
315	        return Err(ReleaseIntentError::UnsupportedTrustProfile.into());
316	    }
317	    let evidence = workspace.git_access().observe_git_commit_trust()?;
318	    if evidence.canonical_root() != workspace.root {
319	        return Err(GraphError::ReleasePreconditionUnmet {
320	            requirement: ReleasePreconditionRequirement::CanonicalRootMatchesWorkspace,
321	        });
322	    }
323	    if checkout == ReleaseCheckout::Detached && evidence.head_disposition() != GitHeadDisposition::Detached {
324	        return Err(GraphError::ReleasePreconditionUnmet {
325	            requirement: ReleasePreconditionRequirement::DetachedHead,
326	        });
327	    }
328	    Ok(evidence)
329	}
330	
331	fn source_from_trust(evidence: &GitCommitTrustEvidence) -> SourceIdentity {
332	    SourceIdentity::GitCommit {
333	        sha: evidence.head().clone(),
334	    }
335	}
