28	/// A package that is itself an npm platform package (its own package.json has
29	/// `os`+`cpu`). An owner's attached (Case E) platform manifests do not count.
30	pub(crate) fn is_platform_package(pkg: &callisto_model::Package) -> bool {
31	    pkg.manifests.iter().any(|m| {
32	        matches!(m.role, callisto_model::ManifestRole::Platform { .. })
33	            && pkg.canonical_manifests().any(|c| c.path == m.path)
34	    })
