37	/// Coordinator-owned identity used to bind a product artifact to the exact
38	/// workflow revision that built it. This is distinct from a historic release
39	/// source during recovery.
40	#[derive(Clone, Debug)]
41	pub struct ArtifactBuildPolicy {
42	    pub repository: GitHubRepository,
43	    pub workflow_path: String,
44	    pub workflow_commit: CommitSha,
45	}
46	
47	pub(crate) type DerivedReleaseInputs = (
48	    ReleaseInputSnapshotV1,
49	    Vec<ReleaseOperation>,
50	    BTreeMap<ReleaseOperationId, PreparedOperation>,
51	    Option<PreparedGitRemote>,
52	    Vec<ArtifactSlotId>,
53	);
54	
55	pub(crate) struct PreparedDerivation {
56	    pub(crate) operations: BTreeMap<ReleaseOperationId, PreparedOperation>,
57	    pub(crate) git_remote: Option<PreparedGitRemote>,
58	}
