60	/// Whether a missing `origin` push URL fails derivation or leaves tags unbound.
61	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
62	pub(crate) enum GitRemoteRequirement {
63	    Required,
64	    /// A preview only: tag operations are derived without a remote identity.
65	    OptionalForPreview,
66	}
67	
68	pub(crate) fn derive_release_intent<R: CommandRunner, D: DependencyResolver>(
69	    workspace: &Workspace<'_, R, D>,
70	    decision: &ReleaseDecisionV1,
71	    source: SourceIdentity,
72	    trust_profile: ExecutionTrustProfileV1,
73	    artifact_policy: Option<&ArtifactBuildPolicy>,
74	    remote: GitRemoteRequirement,
75	) -> Result<ReleaseIntentV1, GraphError> {
