87	pub(crate) fn derive_release_intent_with_prepared<R: CommandRunner, D: DependencyResolver>(
88	    workspace: &Workspace<'_, R, D>,
89	    decision: &ReleaseDecisionV1,
90	    source: SourceIdentity,
91	    trust_profile: ExecutionTrustProfileV1,
92	    artifact_policy: Option<&ArtifactBuildPolicy>,
93	) -> Result<(ReleaseIntentV1, PreparedDerivation), GraphError> {
94	    let (snapshot, operations, prepared, git_remote, slots) =
95	        derive_release_inputs(workspace, decision, source, artifact_policy)?;
96	    let intent = ReleaseIntentV1::new(decision.clone(), snapshot, trust_profile, operations, slots)?;
97	    Ok((
98	        intent,
99	        PreparedDerivation {
100	            operations: prepared,
