106	pub(crate) fn artifact_policy_from_intent(intent: &ReleaseIntentV1) -> Result<Option<ArtifactBuildPolicy>, GraphError> {
107	    let Some(first) = intent.artifact_slots.first() else {
108	        return Ok(None);
109	    };
110	    let policy = &first.attestation_policy;
111	    if intent
112	        .artifact_slots
113	        .iter()
114	        .any(|slot| slot.attestation_policy != *policy)
115	    {
116	        return Err(GraphError::ReleaseInvariant {
117	            detail: "release intent mixes artifact attestation policies".to_owned(),
118	        });
119	    }
120	    Ok(Some(ArtifactBuildPolicy {
121	        repository: policy.repository.clone(),
122	        workflow_path: policy.workflow_path.clone(),
123	        workflow_commit: policy.workflow_commit.clone(),
124	    }))
125	}
