127	pub(crate) fn derive_release_inputs<R: CommandRunner, D: DependencyResolver>(
128	    workspace: &Workspace<'_, R, D>,
129	    decision: &ReleaseDecisionV1,
130	    source: SourceIdentity,
131	    artifact_policy: Option<&ArtifactBuildPolicy>,
132	) -> Result<DerivedReleaseInputs, GraphError> {
133	    derive_release_inputs_with(
134	        workspace,
135	        decision,
136	        source,
137	        artifact_policy,
138	        GitRemoteRequirement::Required,
139	    )
140	}
141	
142	fn derive_release_inputs_with<R: CommandRunner, D: DependencyResolver>(
143	    workspace: &Workspace<'_, R, D>,
144	    decision: &ReleaseDecisionV1,
145	    source: SourceIdentity,
146	    artifact_policy: Option<&ArtifactBuildPolicy>,
147	    remote: GitRemoteRequirement,
148	) -> Result<DerivedReleaseInputs, GraphError> {
149	    if workspace
150	        .config
151	        .product_release
152	        .as_ref()
153	        .is_some_and(|release| release.forge_repository.is_none())
154	    {
155	        return Err(GraphError::ReleaseForgeRepositoryMissing);
156	    }
157	    let mut package_inputs = Vec::new();
158	
159	    let mut selected = BTreeMap::new();
160	    let mut package_ids = BTreeMap::<callisto_model::PackageId, Vec<ReleasePackageId>>::new();
161	    for package in workspace.graph.packages() {
162	        // One canonical manifest per ecosystem is the expected shape, but
163	        // dedup defensively -- `release_package_ids` maps every canonical
164	        // manifest, and two manifests sharing an ecosystem would otherwise
165	        // select/push the same identity twice.
166	        for id in crate::commands::release_decision::release_package_ids(&workspace.identity, package)?
167	            .into_iter()
168	            .collect::<BTreeSet<_>>()
169	        {
170	            if let Some(entry) = decision.entries.iter().find(|entry| entry.package == id) {
171	                selected.insert(id.clone(), (package, entry.target_version.clone()));
172	                package_ids.entry(package.id.clone()).or_default().push(id);
173	            }
174	        }
175	    }
176	    for entry in &decision.entries {
177	        let id = &entry.package;
178	        if !selected.contains_key(id) {
179	            return Err(GraphError::ReleasePackageNotSelected { package: id.clone() });
180	        }
181	    }
182	    require_dependencies_selected(workspace, &selected, &package_ids)?;
183	    let all_packages: Vec<_> = workspace.graph.packages().map(|package| package.id.clone()).collect();
184	    let publish_edges = PublishEdgeFilter::new(
185	        &package_ids.keys().cloned().collect(),
186	        &all_packages,
187	        |id: &callisto_model::PackageId| {
188	            workspace
189	                .graph
190	                .dependencies_of(id)
191	                .map(|edge| (edge.to.clone(), edge.kind))
192	                .collect()
193	        },
194	    )?;
195	
196	    let requires_git_remote = selected.values().any(|(package, _)| {
197	        package
198	            .publish_to
199	            .iter()
200	            .any(|target| !matches!(target, PublishTarget::None))
201	    });
202	    let git_remote = match (requires_git_remote, remote) {
203	        (false, _) => None,
204	        (true, GitRemoteRequirement::Required) => Some(prepared_git_remote(&workspace.root, workspace.runner)?),
205	        (true, GitRemoteRequirement::OptionalForPreview) => optional_git_remote(&workspace.root, workspace.runner)?,
206	    };
207	    if let Some(policy) = artifact_policy {
208	        let remote = git_remote
209	            .as_ref()
210	            .and_then(|remote| remote.github_repository.as_ref())
211	            .ok_or(GraphError::ReleasePreconditionUnmet {
212	                requirement: ReleasePreconditionRequirement::GitHubRemote,
213	            })?;
214	        if remote != &policy.repository {
215	            return Err(GraphError::ReleaseArtifactRepositoryMismatch {
216	                configured: policy.repository.clone(),
217	                remote: remote.clone(),
218	            });
219	        }
220	    }
221	
222	    let mut operations = BTreeMap::<ReleaseOperationId, ReleaseOperation>::new();
223	    let mut prepared = BTreeMap::<ReleaseOperationId, PreparedOperation>::new();
224	    let mut publishes_by_package = BTreeMap::<ReleasePackageId, Vec<ReleaseOperationId>>::new();
225	    // Owner registry publish -> its platform publishes, which must land first.
226	    let mut platforms_by_publish = BTreeMap::<ReleaseOperationId, Vec<ReleaseOperationId>>::new();
227	    let mut tag_by_package = BTreeMap::<ReleasePackageId, ReleaseOperationId>::new();
228	    let mut forge_by_package = BTreeMap::<ReleasePackageId, ReleaseOperationId>::new();
229	
230	    // First construct leaves so dependency prerequisites can refer only to
231	    // exact selected release identities, never PackageId's wildcard matcher.
232	    for (id, (package, version)) in &selected {
233	        let produces_tag = package
234	            .publish_to
235	            .iter()
236	            .any(|target| !matches!(target, PublishTarget::None));
237	        let fingerprint = package_fingerprint(
238	            workspace,
239	            id,
240	            package,
241	            version,
242	            produces_tag.then_some(git_remote.as_ref()).flatten(),
243	        )?;
244	        package_inputs.push(ReleasePackageInputV1 {
245	            package: id.clone(),
246	            fingerprint,
247	        });
248	
249	        let mut publishes = Vec::new();
250	        for target in &package.publish_to {
251	            if !target.is_implemented() {
252	                return Err(GraphError::PublishTargetNotImplemented {
253	                    package: id.clone(),
254	                    target: target.config_str(),
255	                });
256	            }
257	            if target.ecosystem() == Some(id.ecosystem()) {
258	                super::provider::registry::require_observable_registry(id.ecosystem())?;
259	                let binding = prepared_registry_binding(workspace, target, &package.id)?;
260	                let binding_id = RegistryBindingId::new(binding.key.as_str(), binding.identity.clone())?;
261	                let operation =
262	                    ReleaseOperation::registry_publish(id.clone(), version.clone(), binding_id.clone(), Vec::new())?;
263	                // A durable registry operation must have one exact endpoint
264	                // binding. The model-level operation identity currently has
265	                // only a registry key, so reject a second target that would
266	                // collapse to the same operation until the typed binding
267	                // identity is added there.
268	                if prepared.contains_key(operation.id()) {
269	                    return Err(GraphError::ReleaseSelectionInvalid {
270	                        package: id.clone(),
271	                        reason: ReleaseSelectionInvalidReason::DuplicateRegistryTarget,
272	                    });
273	                }
274	                let explicit_access = match target {
275	                    PublishTarget::Npm { access, .. } => *access,
276	                    _ => None,
277	                };
278	                let npm_tag = matches!(target, PublishTarget::Npm { .. })
279	                    .then(|| version.is_prerelease().then_some("next".to_string()))
280	                    .flatten();
281	                if matches!(target, PublishTarget::Npm { .. }) {
282	                    let mut platform_ids = Vec::new();
283	                    for (name, manifest) in workspace.identity.attached_platforms(package) {
284	                        let directory = manifest.parent().unwrap_or(std::path::Path::new(""));
285	                        let platform = PlatformPackageV1::new(
286	                            ReleasePackageId::new(callisto_model::Ecosystem::Npm, name)?,
287	                            directory.to_string_lossy().replace('\\', "/"),
288	                        )?;
289	                        let platform_operation = ReleaseOperation::new(
290	                            callisto_model::ReleaseOperationId::platform_publish(
291	                                id.clone(),
292	                                version.clone(),
293	                                binding_id.clone(),
294	                                platform,
295	                            ),
296	                            Vec::new(),
297	                        )?;
298	                        prepared.insert(
299	                            platform_operation.id().clone(),
300	                            PreparedOperation::RegistryPublish(RegistryPublishOperation {
301	                                package_dir: directory.to_path_buf(),
302	                                package_name: name.to_string(),
303	                                version: version.clone(),
304	                                registry: prepared_registry_binding(workspace, target, &package.id)?,
305	                                npm_access: npm_default_access(name, explicit_access),
306	                                npm_tag: npm_tag.clone(),
307	                                by_directory: true,
308	                            }),
309	                        );
310	                        platform_ids.push(platform_operation.id().clone());
311	                        operations.insert(platform_operation.id().clone(), platform_operation);
312	                    }
313	                    platforms_by_publish.insert(operation.id().clone(), platform_ids);
314	                }
315	                prepared.insert(
316	                    operation.id().clone(),
317	                    PreparedOperation::RegistryPublish(RegistryPublishOperation {
318	                        package_dir: package_dir(package)?,
319	                        package_name: id.name().to_string(),
320	                        version: version.clone(),
321	                        registry: binding,
322	                        npm_access: matches!(target, PublishTarget::Npm { .. })
323	                            .then(|| npm_default_access(id.name(), explicit_access))
324	                            .flatten(),
325	                        npm_tag,
326	                        by_directory: false,
327	                    }),
328	                );
329	                publishes.push(operation.id().clone());
330	                operations.insert(operation.id().clone(), operation);
331	            }
332	        }
333	        publishes.sort();
334	        publishes_by_package.insert(id.clone(), publishes);
335	    }
336	
337	    // Replace each publish leaf with prerequisites from selected dependency
338	    // packages, ordered by the shared publish edge filter.
339	    for (id, (package, _)) in &selected {
340	        let mut prerequisites = BTreeSet::new();
341	        for edge in workspace.graph.dependencies_of(&package.id) {
342	            if !publish_edges.allows(&package.id, &edge.to, edge.kind) {
343	                continue;
344	            }
345	            for dependency_release_id in package_ids.get(&edge.to).into_iter().flatten() {
346	                prerequisites.extend(
347	                    publishes_by_package
348	                        .get(dependency_release_id)
349	                        .into_iter()
350	                        .flatten()
351	                        .cloned(),
352	                );
353	            }
354	        }
355	        for publish_id in publishes_by_package.get(id).into_iter().flatten() {
356	            let operation = operations.get(publish_id).expect("publish operation was constructed");
357	            let mut prerequisites = prerequisites.clone();
358	            prerequisites.extend(platforms_by_publish.get(publish_id).into_iter().flatten().cloned());
359	            let replacement = ReleaseOperation::new(operation.id().clone(), prerequisites.into_iter().collect())?;
360	            operations.insert(publish_id.clone(), replacement);
361	        }
362	    }
363	
364	    for (id, (package, version)) in &selected {
365	        if !package
366	            .publish_to
367	            .iter()
368	            .any(|target| !matches!(target, PublishTarget::None))
369	        {
370	            continue;
371	        }
372	        let tag = ReleaseOperation::tag(
373	            id.clone(),
374	            version.clone(),
375	            publishes_by_package.get(id).cloned().unwrap_or_default(),
376	        )?;
377	        let tag_name = package
378	            .tag_template
379	            .clone()
380	            .unwrap_or_else(|| callisto_model::TagTemplate::default_for(&package.id))
381	            .render(version);
382	        let target = match &source {
383	            SourceIdentity::GitCommit { sha } => sha.clone(),
384	            SourceIdentity::HermeticContent { .. } => {
385	                return Err(GraphError::UnsupportedRelease {
386	                    feature: UnsupportedReleaseFeature::SourceIdentity,
387	                })
388	            }
389	        };
390	        prepared.insert(
391	            tag.id().clone(),
392	            PreparedOperation::Tag(TagOperation {
393	                annotation: format!("Release {tag_name}"),
394	                name: tag_name,
395	                target,
396	            }),
397	        );
398	        tag_by_package.insert(id.clone(), tag.id().clone());
399	        operations.insert(tag.id().clone(), tag);
400	    }
401	    for (id, (package, version)) in &selected {
402	        if package
403	            .publish_to
404	            .iter()
405	            .any(|target| matches!(target, PublishTarget::GitHubRelease))
406	        {
407	            let tag = tag_by_package.get(id).expect("release point has tag").clone();
408	            let operation = ReleaseOperation::forge_release(id.clone(), version.clone(), vec![tag])?;
409	            let tag = match prepared.get(operation.prerequisites().first().expect("forge release has tag")) {
410	                Some(PreparedOperation::Tag(prepared_tag)) => prepared_tag.name.clone(),
411	                _ => {
412	                    return Err(GraphError::ReleaseInvariant {
413	                        detail: format!(
414	                            "forge release `{:?}` prerequisite is not a prepared Tag operation",
415	                            operation.id()
416	                        ),
417	                    })
418	                }
419	            };
420	            prepared.insert(
421	                operation.id().clone(),
422	                PreparedOperation::ForgeRelease(ForgeReleaseOperation {
423	                    tag,
424	                    prerelease: version.is_prerelease(),
425	                    notes: release_notes(&workspace.root, package.changelog.as_deref(), version),
426	                }),
427	            );
428	            forge_by_package.insert(id.clone(), operation.id().clone());
429	            operations.insert(operation.id().clone(), operation);
430	        }
431	    }
432	
433	    let mut artifact_slots = Vec::new();
434	    let mut uploads_by_package = BTreeMap::<ReleasePackageId, Vec<ReleaseOperationId>>::new();
435	    if let (Some(product), Some(policy)) = (&workspace.config.product_release, artifact_policy) {
436	        require_product_package_publishes_to_forge(workspace, &product.package)?;
437	        for (id, (package, _)) in &selected {
438	            // Workspace package identities may remain bare even when a
439	            // policy intentionally qualifies the product by ecosystem. Use
440	            // the model's compatibility relation and retain the explicit
441	            // ecosystem check so a same-name package in another ecosystem
442	            // cannot acquire the product's binary release slots.
443	            if !product.package.matches(&package.id) || product.package.ecosystem() != Some(id.ecosystem()) {
444	                continue;
445	            }
446	            let forge = forge_by_package.get(id).ok_or_else(|| GraphError::ReleaseInvariant {
447	                detail: format!("product package `{id}` has no forge release operation"),
448	            })?;
449	            let tag = match prepared.get(forge) {
450	                Some(PreparedOperation::ForgeRelease(prepared_forge)) => prepared_forge.tag.clone(),
451	                _ => {
452	                    return Err(GraphError::ReleaseInvariant {
453	                        detail: format!("product forge release `{forge:?}` is not prepared"),
454	                    })
455	                }
456	            };
457	            for artifact in &product.artifacts {
458	                // The slot names the package whose build produced the bytes, which
459	                // need not be the product -- a plugin can ship on the product's
460	                // release. Every slot still attaches to the product's one release.
461	                let (owner_id, owner_version) = selected
462	                    .iter()
463	                    .find(|(candidate, (pkg, _))| {
464	                        artifact.package.matches(&pkg.id) && artifact.package.ecosystem() == Some(candidate.ecosystem())
465	                    })
466	                    .map(|(candidate, (_, owner_version))| (candidate.clone(), owner_version.clone()))
467	                    .ok_or_else(|| GraphError::ReleaseArtifactOwnerNotReleased {
468	                        asset: artifact.asset_name.clone(),
469	                        package: artifact.package.to_string(),
470	                    })?;
471	                let slot = ArtifactSlotId::new(
472	                    owner_id.clone(),
473	                    owner_version.clone(),
474	                    &artifact.target,
475	                    artifact.asset_name.clone(),
476	                    policy.repository.clone(),
477	                    policy.workflow_path.clone(),
478	                    policy.workflow_commit.clone(),
479	                )
480	                .map_err(|error| GraphError::ReleaseInvariant {
481	                    detail: format!("invalid configured artifact slot: {error}"),
482	                })?;
483	                let operation = ReleaseOperation::artifact_upload(slot.clone(), vec![forge.clone()])?;
484	                prepared.insert(
485	                    operation.id().clone(),
486	                    PreparedOperation::ArtifactUpload(ArtifactUploadOperation {
487	                        slot: slot.clone(),
488	                        tag: tag.clone(),
489	                        prerelease: owner_version.is_prerelease(),
490	                    }),
491	                );
492	                uploads_by_package
493	                    .entry(owner_id.clone())
494	                    .or_default()
495	                    .push(operation.id().clone());
496	                operations.insert(operation.id().clone(), operation);
497	                artifact_slots.push(slot);
498	            }
499	        }
500	    }
501	
502	    // Publishing is the last forge step: a GitHub Release is only complete
503	    // once every asset it carries has been uploaded to it as a draft.
504	    for (id, (_, version)) in &selected {
505	        let Some(forge) = forge_by_package.get(id) else {
506	            continue;
507	        };
508	        let mut prerequisites = vec![forge.clone()];
509	        prerequisites.extend(uploads_by_package.get(id).into_iter().flatten().cloned());
510	        let operation = ReleaseOperation::forge_publish(id.clone(), version.clone(), prerequisites)?;
511	        let tag = match prepared.get(forge) {
512	            Some(PreparedOperation::ForgeRelease(prepared_forge)) => prepared_forge.tag.clone(),
513	            _ => {
514	                return Err(GraphError::ReleaseInvariant {
515	                    detail: format!("forge publish `{:?}` has no prepared draft release", operation.id()),
516	                })
517	            }
518	        };
519	        prepared.insert(
520	            operation.id().clone(),
521	            PreparedOperation::ForgePublish(ForgePublishOperation {
522	                tag,
523	                prerelease: version.is_prerelease(),
524	            }),
525	        );
526	        operations.insert(operation.id().clone(), operation);
527	    }
528	
529	    Ok((
530	        ReleaseInputSnapshotV1::new(source, package_inputs)?,
531	        canonical_operation_order(operations)?,
532	        prepared,
533	        git_remote,
534	        artifact_slots,
535	    ))
536	}
