538	/// Every unreleased, publishable workspace package a selected package reaches
539	/// through a runtime, optional, or peer edge must be selected with it, or the
540	/// selected package would publish pointing at a version that does not exist.
541	/// Standalone npm platform packages are one case of this.
542	fn require_dependencies_selected<R: CommandRunner, D: DependencyResolver>(
543	    workspace: &Workspace<'_, R, D>,
544	    selected: &BTreeMap<ReleasePackageId, (&callisto_model::Package, Version)>,
545	    package_ids: &BTreeMap<callisto_model::PackageId, Vec<ReleasePackageId>>,
546	) -> Result<(), GraphError> {
547	    let mut base_versions = None;
548	    for (package, _) in selected.values() {
549	        for edge in workspace.graph.dependencies_of(&package.id) {
550	            if !matches!(edge.kind, DepKind::Runtime | DepKind::Optional | DepKind::Peer)
551	                || package_ids.contains_key(&edge.to)
552	            {
553	                continue;
554	            }
555	            let Some(dependency) = workspace
556	                .graph
557	                .packages()
558	                .find(|candidate| candidate.id == edge.to && has_dispatchable_target(candidate))
559	            else {
560	                continue;
561	            };
562	            if base_versions.is_none() {
563	                base_versions = Some(workspace.base_versions()?);
564	            }
565	            let tags = workspace.tags()?;
566	            let released = base_versions
567	                .as_ref()
568	                .and_then(|versions| versions.get(&dependency.id))
569	                .is_some_and(|current| version_is_tagged(tags, &dependency.id, current));
570	            if !released {
571	                let id = crate::commands::release_decision::release_package_ids(&workspace.identity, dependency)?
572	                    .into_iter()
573	                    .next()
574	                    .ok_or_else(|| GraphError::ReleaseInvariant {
575	                        detail: format!("package `{}` has no release identity", dependency.id.display_name()),
576	                    })?;
577	                return Err(GraphError::ReleaseSelectionInvalid {
578	                    package: id,
579	                    reason: ReleaseSelectionInvalidReason::DependencyNotSelected,
580	                });
581	            }
582	        }
583	    }
584	    Ok(())
585	}
