587	/// A configured product package must exist and publish to github-release; otherwise
588	/// derivation would silently yield zero artifact slots.
589	fn require_product_package_publishes_to_forge<R: CommandRunner, D: DependencyResolver>(
590	    workspace: &Workspace<'_, R, D>,
591	    product: &callisto_model::PackageId,
592	) -> Result<(), GraphError> {
593	    let mut found = false;
594	    for package in workspace.graph.packages() {
595	        let is_product = crate::commands::release_decision::release_package_ids(&workspace.identity, package)?
596	            .iter()
597	            .any(|id| product.matches(&package.id) && product.ecosystem() == Some(id.ecosystem()));
598	        if !is_product {
599	            continue;
600	        }
601	        found = true;
602	        if package
603	            .publish_to
604	            .iter()
605	            .any(|target| matches!(target, PublishTarget::GitHubRelease))
606	        {
607	            return Ok(());
608	        }
609	    }
610	    let detail = if found {
611	        format!("product-package `{product}` does not publish to github-release")
612	    } else {
613	        format!("product-package `{product}` is not a package in this workspace")
614	    };
615	    Err(crate::error::ConfigError::InvalidProductRelease { detail }.into())
616	}
