618	fn package_fingerprint<R: CommandRunner, D: DependencyResolver>(
619	    workspace: &Workspace<'_, R, D>,
620	    id: &ReleasePackageId,
621	    package: &callisto_model::Package,
622	    version: &Version,
623	    git_remote: Option<&PreparedGitRemote>,
624	) -> Result<SemanticInputDigest, GraphError> {
625	    let mut transcript = CanonicalTranscript::semantic_input_v1();
626	    transcript.push_str("package.id", &id.to_string());
627	    transcript.push_str("package.version", version.render());
628	    for manifest in &package.manifests {
629	        let path = workspace.root.join(&manifest.path);
630	        let bytes = std::fs::read(&path).map_err(|error| GraphError::ReleaseInputRead {
631	            path: manifest.path.clone(),
632	            message: error.to_string(),
633	        })?;
634	        transcript.push_str("manifest.path", &manifest.path.display().to_string());
635	        transcript.push_str("manifest.bytes", digest_bytes("manifest", &bytes).as_str());
636	        transcript.push_str("manifest.role", &manifest_role_text(&manifest.role));
637	        transcript.push_str("manifest.format", manifest.format.ecosystem().prefix());
638	    }
639	    transcript.push_str("package.trigger", release_trigger_text(package.release_trigger));
640	    transcript.push_str(
641	        "package.tag",
642	        &package
643	            .tag_template
644	            .as_ref()
645	            .map_or_else(|| "default".to_string(), |tag| tag.as_str()),
646	    );
647	    let npm_name = workspace
648	        .identity
649	        .native_name(&package.id, callisto_model::Ecosystem::Npm)
650	        .unwrap_or(package.id.name());
651	    for target in &package.publish_to {
652	        transcript.push_str(
653	            "package.target",
654	            target_fingerprint(workspace, &package.id, npm_name, target)?.as_str(),
655	        );
656	    }
657	    if let Some(remote) = git_remote {
658	        transcript.push_str("package.gitRemote", remote.identity.as_str());
659	    }
660	    Ok(SemanticInputDigest::from_transcript(&transcript))
661	}
