691	pub(crate) fn canonical_operation_order(
692	    operations: BTreeMap<ReleaseOperationId, ReleaseOperation>,
693	) -> Result<Vec<ReleaseOperation>, GraphError> {
694	    let mut remaining: BTreeMap<_, usize> = operations
695	        .iter()
696	        .map(|(id, operation)| (id.clone(), operation.prerequisites().len()))
697	        .collect();
698	    let mut dependents = BTreeMap::<ReleaseOperationId, Vec<ReleaseOperationId>>::new();
699	    for (id, operation) in &operations {
700	        for prerequisite in operation.prerequisites() {
701	            dependents.entry(prerequisite.clone()).or_default().push(id.clone());
702	        }
703	    }
704	    let mut ready: BTreeSet<_> = remaining
705	        .iter()
706	        .filter_map(|(id, count)| (*count == 0).then_some(id.clone()))
707	        .collect();
708	    let mut ordered = Vec::with_capacity(operations.len());
709	    while let Some(id) = ready.pop_first() {
710	        ordered.push(operations.get(&id).expect("known operation").clone());
711	        for dependent in dependents.get(&id).into_iter().flatten() {
712	            let count = remaining.get_mut(dependent).expect("known operation");
713	            *count -= 1;
714	            if *count == 0 {
715	                ready.insert(dependent.clone());
716	            }
717	        }
718	    }
719	    if ordered.len() != operations.len() {
720	        return Err(GraphError::ReleaseInvariant {
721	            detail: "release operation DAG contains a cycle: topological sort could not order every operation"
722	                .to_string(),
723	        });
724	    }
725	    Ok(ordered)
726	}
