728	fn digest_bytes(tag: &str, bytes: &[u8]) -> SemanticInputDigest {
729	    let mut transcript = CanonicalTranscript::semantic_input_v1();
730	    transcript.push_bytes(tag, bytes);
731	    SemanticInputDigest::from_transcript(&transcript)
732	}
