734	fn target_fingerprint<R: CommandRunner, D: DependencyResolver>(
735	    workspace: &Workspace<'_, R, D>,
736	    package: &callisto_model::PackageId,
737	    npm_name: &str,
738	    target: &PublishTarget,
739	) -> Result<SemanticInputDigest, GraphError> {
740	    let mut transcript = CanonicalTranscript::semantic_input_v1();
741	    // Single source of truth for the "kind" string, shared with
742	    // `PublishTarget::config_str`'s other diagnostic/config-parsing callers
743	    // instead of re-hardcoding these per-variant literals here too.
744	    transcript.push_str("target.kind", target.config_str());
745	    match target {
746	        PublishTarget::GitHubRelease | PublishTarget::None => {}
747	        PublishTarget::CratesIo => {
748	            push_registry_binding(
749	                &mut transcript,
750	                prepared_registry_binding(workspace, target, package)?.identity,
751	            )?;
752	        }
753	        PublishTarget::Npm { access, .. } => {
754	            push_registry_binding(
755	                &mut transcript,
756	                prepared_registry_binding(workspace, target, package)?.identity,
757	            )?;
758	            transcript.push_str(
759	                "target.access",
760	                match npm_default_access(npm_name, *access) {
761	                    Some(callisto_model::NpmAccess::Public) => "public",
762	                    Some(callisto_model::NpmAccess::Restricted) => "restricted",
763	                    None => "default",
764	                },
765	            );
766	        }
767	        PublishTarget::Pypi { .. } | PublishTarget::NuGet { .. } => {
768	            push_registry_binding(
769	                &mut transcript,
770	                prepared_registry_binding(workspace, target, package)?.identity,
771	            )?;
772	        }
773	        #[allow(unreachable_patterns)]
774	        _ => {
775	            return Err(GraphError::UnsupportedRelease {
776	                feature: UnsupportedReleaseFeature::PublishTarget,
777	            })
778	        }
779	    }
780	    Ok(SemanticInputDigest::from_transcript(&transcript))
781	}
