783	fn push_registry_binding(
784	    transcript: &mut CanonicalTranscript,
785	    fingerprint: RegistryBindingDigest,
786	) -> Result<(), GraphError> {
787	    transcript.push_str("target.registry", fingerprint.as_str());
788	    Ok(())
789	}
