1	//! Interface for typed managed release-pull-request decisions, and for
2	//! building the exact forge commit-API file changes the executor submits.
3	//! `decide` and `verify` are read-only; `commit-plan` reads the Git index
4	//! and worktree but writes no forge state itself -- the executor script is
5	//! the only thing that ever calls GitHub.
6	
7	use std::process::ExitCode;
8	
9	use callisto_graph::commands::{status, StatusOptions};
10	use callisto_model::{
11	    ApplyPermit, CommitSha, GitHubRepository, ReleasePrActionV2, ReleasePrCommitPlanV1, ReleasePrConfigV1,
12	    ReleasePrDecisionError, ReleasePrDecisionV2, ReleasePrSnapshotV2,
13	};
14	use callisto_vcs::GitAccess;
15	
16	use crate::cli::{
17	    GlobalArgs, OutputFormat, ReleasePrArgs, ReleasePrCommitPlanArgs, ReleasePrDecideArgs, ReleasePrVerifyArgs,
18	};
19	use crate::commands::read_json_arg;
20	use crate::error::CliError;
21	use crate::output::write_json;
22	use crate::runner::CliCommandRunner;
23	use crate::workspace::load_workspace;
24	
25	pub fn handle(args: ReleasePrArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
26	    match args {
27	        ReleasePrArgs::Decide(args) => decide(args, global),
28	        ReleasePrArgs::Verify(args) => verify(args, global),
29	        ReleasePrArgs::CommitPlan(args) => commit_plan(args, global),
30	    }
31	}
32	
33	fn verify(args: ReleasePrVerifyArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
34	    let decision: ReleasePrDecisionV2 = serde_json::from_str(&read_json_arg(&args.decision)?)
35	        .map_err(|error| CliError::Other(format!("invalid release PR decision: {error}")))?;
36	    let snapshot: ReleasePrSnapshotV2 = serde_json::from_str(&read_json_arg(&args.snapshot)?)
37	        .map_err(|error| CliError::Other(format!("invalid release PR snapshot: {error}")))?;
38	    decision.verify_snapshot(&snapshot)?;
39	    match global.format {
40	        OutputFormat::Json => write_json(
41	            &mut std::io::stdout(),
42	            &serde_json::json!({"schemaVersion": ReleasePrDecisionV2::SCHEMA_VERSION, "ok": true}),
43	        )?,
44	        OutputFormat::Text => println!("release PR decision still matches forge snapshot"),
45	    }
46	    Ok(ExitCode::SUCCESS)
47	}
48	
49	fn decide(args: ReleasePrDecideArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
50	    let snapshot: ReleasePrSnapshotV2 = serde_json::from_str(&read_json_arg(&args.snapshot)?)
51	        .map_err(|error| CliError::Other(format!("invalid release PR snapshot: {error}")))?;
52	    let repository =
53	        GitHubRepository::parse(&args.repository).map_err(|_error| ReleasePrDecisionError::InvalidRepository {
